function C(l,o,n){let i=(o||"").trim();if(!i)return"";let p=i.split(","),m=p[0].trim(),c=p.slice(1).map(e=>e.trim()).filter(Boolean),t=m.toUpperCase();const s=(l||"").trim(),a=(n||"").trim();s&&s!=="-"&&!t.toUpperCase().startsWith(s.toUpperCase())&&(t=`${s} ${t}`);const r=[...c];if(a&&a!=="-"){const e=a.replace(/^,\s*/,"").trim();e&&!r.some(f=>f.toUpperCase()===e.toUpperCase())&&!t.toUpperCase().includes(e.toUpperCase())&&r.push(e)}return r.length>0&&(t=`${t}, ${r.join(", ")}`),t}export{C as f};
